Bp21Bulk.ListOfBp21:
{{- $d := .Doc}}
{{- range $k, $rows := .Related}}
{{- range $rows}}
{{- $tin := digits .slip_nik}}
{{- if eq (len (digits .slip_npwp)) 16}}{{$tin = digits .slip_npwp}}{{else if eq (len (digits .slip_npwp)) 15}}{{$tin = print "0" (digits .slip_npwp)}}{{end}}
{{- $m := 100}}{{if not .has_tax_id}}{{$m = 120}}{{end}}

			{{dec $d.month 0}}
			{{$d.year}}
			{{$tin}}
			{{$tin}}000000
			{{if eq (slice .ptkp_status 0 1) "t"}}TK/{{slice .ptkp_status 2}}{{else}}K/{{slice .ptkp_status 1}}{{end}}
			N/A
			{{if eq $k "high"}}21-100-30{{else}}21-100-24{{end}}
			{{dec .gross_taxable 0}}
			{{if eq $k "high"}}50{{else}}100{{end}}
			{{if eq $k "zero"}}0{{else if eq $k "low"}}{{dec (div (mul 5 $m) 1000) 2}}{{else}}{{dec (div (mul .daily_pph21 200) .gross_taxable) 4}}{{end}}
			Other
			{{.name}}
			{{isodate .run_period_to}}
			{{$d.seller_nitku}}
			{{isodate $d.withholding_date}}

{{- end}}
{{- end}}
